```{.r .cell-code}
data %>% 
  tbl_summary(
    by = trt,
    statistic = list(
      all_continuous() ~ "{mean} ({sd})",
      all_categorical() ~ "{n} ({p}%)"
    )
  ) %>% 
  add_p() %>% 
  modify_header(label = "**Variable**") %>% 
  bold_labels()
```

